using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public sealed class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;
    private static IChatClient _evaluatorClient = null!;
    private static ReportingConfiguration _reportingConfig = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        await _appHost.BuildAsync();

        var app = await _appHost.StartAsync();
        _chatClient = app.Services.GetRequiredService<IChatClient>();
        _evaluatorClient = app.Services.GetRequiredService<IChatClient>();

        _reportingConfig = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is not null)
        {
            await _appHost.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_ReturnsRelevantResponse()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var evaluators = new IEvaluator[]
        {
            new RelevanceTruthAndCompletenessEvaluator(),
            new CoherenceEvaluator()
        };

        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_ReturnsRelevantResponse));

        var result = await scenario.EvaluateAsync(
            messages,
            evaluators,
            _evaluatorClient);

        foreach (var metric in result)
        {
            Assert.IsFalse(
                metric.Rating is not null && metric.Rating < 3,
                $"Metric '{metric.Name}' scored below threshold: {metric.Rating}");
        }
    }

    [TestMethod]
    public async Task Chat_HandlesFollowUpQuestions()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Tell me about photosynthesis."),
        };

        var response1 = await _chatClient.GetResponseAsync(messages);
        messages.Add(response1.Message);
        messages.Add(new ChatMessage(ChatRole.User, "What role does chlorophyll play in that process?"));

        var response2 = await _chatClient.GetResponseAsync(messages);
        messages.Add(response2.Message);

        var evaluators = new IEvaluator[]
        {
            new RelevanceTruthAndCompletenessEvaluator(),
            new CoherenceEvaluator()
        };

        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_HandlesFollowUpQuestions));

        var result = await scenario.EvaluateAsync(
            messages,
            evaluators,
            _evaluatorClient);

        foreach (var metric in result)
        {
            Assert.IsFalse(
                metric.Rating is not null && metric.Rating < 3,
                $"Metric '{metric.Name}' scored below threshold: {metric.Rating}");
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var path = Path.Combine(
            Path.GetDirectoryName(typeof(EvaluationTests).Assembly.Location)!,
            "evaluation-report");

        return DiskBasedReportingConfiguration.Create(storageRootPath: path);
    }
}

